package pe.edu.upeu.entregable1.utils;import java.util.Scanner;public class Lectura {    private static Scanner teclado = new Scanner(System.in);    public String cadena() {        return teclado.nextLine();    }    public String Mayus() {        return cadena().toUpperCase();    }    public String Minus() {        return cadena().toLowerCase();    }    public int entero(){        return Integer.parseInt(cadena());    }    public Double decimal(){        return Double.parseDouble(cadena());    }    public char letra(){        return cadena().charAt(0);    }    public void cerrar(){        teclado.close();    }}